package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
	"runtime"
)

// Writer is a binary serializer that appends sequentially to an internal byte
// slice using little-endian encoding. It accumulates errors silently: once an
// error is set, all subsequent writes are no-ops and Bytes() returns an empty
// slice.
type Writer struct {
	p   []byte
	err error
}

// NewWriter returns an empty Writer.
func NewWriter() *Writer {
	return &Writer{}
}

// NewWriterCap returns a Writer whose backing buffer is pre-allocated with a
// capacity of at least n bytes, so that writes totaling n bytes do not cause
// reallocation.
func NewWriterCap(n int) *Writer {
	if n < 0 {
		n = 0
	}
	return &Writer{p: make([]byte, 0, n)}
}

// setErr records an error (once) that includes the caller's file:line.
// skip is the number of stack frames between the public method and setErr.
func (w *Writer) setErr(skip int, format string, args ...any) {
	if w.err != nil {
		return
	}
	_, file, line, ok := runtime.Caller(skip + 1)
	if !ok {
		file, line = "?", 0
	}
	msg := fmt.Sprintf(format, args...)
	w.err = fmt.Errorf("%s at %s:%d", msg, file, line)
}

// U8 appends v as 1 byte.
func (w *Writer) U8(v uint8) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, v)
}

// U16 appends v as 2 little-endian bytes.
func (w *Writer) U16(v uint16) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint16(w.p, v)
}

// U32 appends v as 4 little-endian bytes.
func (w *Writer) U32(v uint32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, v)
}

// U64 appends v as 8 little-endian bytes.
func (w *Writer) U64(v uint64) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint64(w.p, v)
}

// F32 appends v as 4 little-endian IEEE 754 bytes.
func (w *Writer) F32(v float32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, math.Float32bits(v))
}

// Str appends the raw bytes of s with no length prefix.
func (w *Writer) Str(s string) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, s...)
}

// U32LenStr appends a 4-byte little-endian uint32 length prefix followed by the
// bytes of s.
func (w *Writer) U32LenStr(s string) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, uint32(len(s)))
	w.p = append(w.p, s...)
}

// U8LenStr appends a 1-byte uint8 length prefix followed by the bytes of s. If
// the length of s exceeds 255 bytes, an error is set and the buffer is left
// unchanged.
func (w *Writer) U8LenStr(s string) {
	if w.err != nil {
		return
	}
	if len(s) > 255 {
		w.setErr(1, "string length %d exceeds 255", len(s))
		return
	}
	w.p = append(w.p, uint8(len(s)))
	w.p = append(w.p, s...)
}

// Raw appends all bytes from b.
func (w *Writer) Raw(b []byte) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, b...)
}

// Obj calls v.MarshalBinary and appends the returned bytes. If MarshalBinary
// returns an error, it is stored in the Writer.
func (w *Writer) Obj(v encoding.BinaryMarshaler) {
	if w.err != nil {
		return
	}
	b, err := v.MarshalBinary()
	if err != nil {
		w.setErr(1, "obj marshal: %v", err)
		return
	}
	w.p = append(w.p, b...)
}

// Bytes returns the accumulated buffer. If an error has been recorded, it
// returns a zero-length slice.
func (w *Writer) Bytes() []byte {
	if w.err != nil {
		return []byte{}
	}
	return w.p
}

// Err returns the accumulated error, or nil if none occurred.
func (w *Writer) Err() error {
	return w.err
}
